
import csv
import os
from datetime import datetime

# CSV file generated by Module 4
ALERT_FILE = "unauthorized_process_alerts.csv"

# Output report file
REPORT_FILE = "security_monitoring_report.txt"


def generate_report():

    alerts = []

    # Read alerts from CSV if available
    if os.path.exists(ALERT_FILE):

        with open(ALERT_FILE, "r", encoding="utf-8") as file:
            reader = csv.DictReader(file)

            for row in reader:
                alerts.append(row)

    else:
        print("No alert CSV file found.")
        print("Generating report with zero alerts.")

    # Calculate alert statistics
    total_alerts = len(alerts)

    high_alerts = sum(
        1 for alert in alerts
        if alert.get("Severity") == "HIGH"
    )

    medium_alerts = sum(
        1 for alert in alerts
        if alert.get("Severity") == "MEDIUM"
    )

    low_alerts = sum(
        1 for alert in alerts
        if alert.get("Severity") == "LOW"
    )

    # Generate report
    report = []

    report.append("=" * 60)
    report.append(" WINDOWS SECURITY MONITORING REPORT")
    report.append("=" * 60)

    report.append(
        "Report Generated: "
        + datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    )

    report.append("")
    report.append("SECURITY SUMMARY")
    report.append("-" * 60)

    report.append(f"Total Alerts: {total_alerts}")
    report.append(f"High Severity Alerts: {high_alerts}")
    report.append(f"Medium Severity Alerts: {medium_alerts}")
    report.append(f"Low Severity Alerts: {low_alerts}")

    report.append("")

    if total_alerts == 0:
        report.append("Status: No security alerts recorded.")
    else:
        report.append("Status: Security alerts recorded.")

    report.append("")
    report.append("ALERT DETAILS")
    report.append("-" * 60)

    if total_alerts == 0:
        report.append("No alert details available.")

    for alert in alerts:

        report.append("")

        report.append(
            "Process Name: " + alert.get("Process_Name", "Unknown")
        )

        report.append(
            "Process ID: " + str(alert.get("PID", "Unknown"))
        )

        report.append(
            "Severity: " + alert.get("Severity", "Unknown")
        )

        report.append(
            "Executable Path: "
            + alert.get("Executable_Path", "Unknown")
        )

        report.append(
            "Timestamp: " + alert.get("Timestamp", "Unknown")
        )

        report.append(
            "Alert: " + alert.get("Alert", "Unknown")
        )

    report.append("")
    report.append("=" * 60)
    report.append(" END OF REPORT")
    report.append("=" * 60)

    # Save report to text file
    with open(REPORT_FILE, "w", encoding="utf-8") as file:
        file.write("\n".join(report))

    print("\nSecurity report generated successfully!")
    print("Report saved as:", REPORT_FILE)


if __name__ == "__main__":
    generate_report()

